import java.util.*;
import java.io.*;

public class Main {
    static int n, m, P;
    static int[][] dwu;
    static long[] dp1;
    static long[][] dp2, dp3;
    static long[] count_arr;

    static void self_multiply(LongWrapper a, int b) {
        a.value = (a.value * b) % P;
    }

    static int multiply(int a, int b) {
        return (int)((long)a * b % P);
    }

    static void add_modulo(LongWrapper a, int b) {
        a.value += b;
        if (a.value >= P) a.value -= P;
    }

    static class LongWrapper {
        long value;
        LongWrapper(long v) { this.value = v; }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        P = Integer.parseInt(st.nextToken());

        dwu = new int[n + 2][n + 2];
        dp1 = new long[m + 2];
        dp2 = new long[n + 2][m + 2];
        dp3 = new long[n + 2][m + 2];
        count_arr = new long[m + 2];

        for (int i = 0; i <= n + 1; i++) {
            for (int j = 0; j <= i; j++) {
                if (j == 0) {
                    dwu[i][j] = 1;
                } else {
                    dwu[i][j] = dwu[i - 1][j] + dwu[i - 1][j - 1];
                    if (dwu[i][j] >= P) dwu[i][j] -= P;
                }
            }
        }

        // Initialize dp1 and count_arr
        Arrays.fill(dp1, 0);
        count_arr[0] = 1;

        for (int i = 1; i <= m; i++) {
            for (int j = 0; j < i; j++) {
                long val = 0;
                val = (val + (long)multiply((int)dp1[j], (int)count_arr[i - j - 1])) % P;
                val = (val + (long)multiply((int)dp1[i - j - 1], (int)count_arr[j])) % P;
                long tempVal = val;
                tempVal = (tempVal * (j + 1)) % P;

                long addTerm = (long)multiply((int)count_arr[i - j - 1], (int)count_arr[j]);
                addTerm = (addTerm * j * (j + 1) / 2) % P;

                tempVal = (tempVal + addTerm) % P;

                long temp = dwu[i - 1][j];
                temp = (temp * count_arr[j]) % P;
                temp = (temp * count_arr[i - j - 1]) % P;
                temp = (temp * (j + 1)) % P;

                add_modulo(new LongWrapper(dp1[i]), (int)temp);
                add_modulo(new LongWrapper(count_arr[i]), (int)temp);
                add_modulo(new LongWrapper(count_arr[i]), (int)temp);
            }
            // Double the count_arr[i] and dp1[i]
            count_arr[i] = (count_arr[i] + count_arr[i]) % P;
            dp1[i] = (dp1[i] + dp1[i]) % P;
        }

        // Initialize dp2 and dp3
        for (int i = 0; i <= n + 1; i++) {
            Arrays.fill(dp2[i], 0);
            Arrays.fill(dp3[i], 0);
        }
        dp2[0][0] = 1;

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                for (int k = 0; k <= m; k++) {
                    if (j + k <= m && i + k + 1 <= n + 1) {
                        long val = dp2[i][j];
                        val = (val * dwu[m - j][k]) % P;
                        val = (val * count_arr[k]) % P;

                        long val3 = dp3[i][j];
                        val3 = (val3 * count_arr[k]) % P;
                        val3 = (val3 + (long)multiply((int)dp1[k], (int)dp2[i][j])) % P;
                        val3 = (val3 * dwu[m - j][k]) % P;

                        dp3[i + k + 1][j + k] = (dp3[i + k + 1][j + k] + val3) % P;
                        dp2[i + k + 1][j + k] = (dp2[i + k + 1][j + k] + val) % P;
                    }
                }
            }
        }

        System.out.println(dp3[n + 1][m]);
    }
}
